扫描命中行的代码上下文（±25 行窗口，L<n> 为包内原始行号）：
L1: // The calls to Datacircle's open API: https://api.datacircle.dev/v1 (its spec: https://api.datacircle.dev/v1/openapi.json).
L2: /** The API's address. */
L3: export const BASE_URL = 'https://api.datacircle.dev/v1';
L4: /** This package's version, sent in each call's User-Agent where the runtime lets a call set one. */
L5: export const VERSION = '0.1.0';
L6: /** An answer of 4xx: the API's own words, given back as the tool's result. */
L7: export class ApiError extends Error {
L8:     status;
L9:     constructor(status, message) {
L10:         super(message);
L11:         this.status = status;
L12:         this.name = 'ApiError';
L13:     }
L14: }
L15: export class Client {
L16:     base;
L17:     fetch;
L18:     constructor(options = {}) {
L19:         this.base = (options.baseURL ?? BASE_URL).replace(/\/+$/, '');
L20:         this.fetch = options.fetch ?? ((input, init) => globalThis.fetch(input, init));
L21:     }
L22:     /** Calls one path and gives its JSON. A 429 is waited for once, a minute at most. */
L23:     async get(path, query = {}, signal) {
L24:         const params = new URLSearchParams();
L25:         for (const [key, value] of Object.entries(query)) {
L26:             if (value !== undefined && value !== null && value !== '')
L27:                 params.set(key, String(value));
L28:         }
L29:         const search = params.toString();
L30:         const url = this.base + path + (search !== '' ? '?' + search : '');
L31:         const headers = { Accept: 'application/json' };
L32:         // A browser sends its own User-Agent, and one set here would make the call ask the API's CORS first.
L33:         if (globalThis.process?.versions?.node) {
L34:             headers['User-Agent'] = `datacircle-opencode/${VERSION}`;
L35:         }
L36:         for (let attempt = 0;; attempt++) {
L37:             let response;
L38:             try {
L39:                 response = await this.fetch(url, { headers, signal });
L40:             }
L41:             catch (error) {
L42:                 if (signal?.aborted)
L43:                     throw error;
L44:                 throw new Error(`datacircle: ${error.message}`, { cause: error });
L45:             }

{
